}

/// <summary>
/// Values of the engine's RemoteSnapshotFormat.
/// </summary>
public enum RemoteSnapshotFormat
{
    /// <summary>
    /// The packed transform (2 mm steps, two bytes of turn while upright): the smallest record for most things, and
    /// what Automatic uses for players and moving objects.
    /// </summary>
    Legacy = 0,
    /// <summary>
    /// Exact floats.
    /// </summary>
    ExactTransform = 1,
    /// <summary>
    /// Finer steps (0.1 mm) and a full rotation.
    /// </summary>
    QuantizedTransform = 2,
    /// <summary>
    /// A physics body shown in the past, with how it is moving: a finely packed position and rotation plus both
    /// velocities, about a third of the size of a full record. For many small bodies clients only watch.
    /// </summary>
    QuantizedBody = 3,
}

/// <summary>
/// Values of the engine's ShellDentMode.
/// </summary>
public enum ShellDentMode
{
    /// <summary>
    /// The object's collider takes every hit, so nothing passes into the shell (make the collider the shape of the
    /// mesh); a hit at Dent Speed or faster presses the shell in around where it landed. The shell itself only
    /// follows its object.
    /// </summary>
    FromImpacts = 0,
    /// <summary>
    /// The shell meets things itself and is pushed in where it touches them (it can fold round a post), so the
    /// collider sits a little inside the mesh (by about Dent Depth). Things can press into the shell that far.
    /// </summary>
    FromSurface = 1,
}

/// <summary>
/// How a terrain decides where it has ground.
/// </summary>
