{
    /// <summary>
    /// Square tiles placed by hand, flat until sculpted (or shaped by the terrain's generator).
    /// </summary>
    Fixed = 0,
    /// <summary>
    /// Generated around the camera without end, by the terrain's generator.
    /// </summary>
    Endless = 1,
}

/// <summary>
/// Values of the engine's VoxelShape.
